92	\chapter{Introduction}\label{ch:intro}
93	
94	\section{Squarefree numbers in arithmetic progressions}
95	
96	Let $\mu$ be the Möbius function, so that $\mu^2(n)$ is the indicator function of the squarefree positive integers. For a modulus $q\ge1$, an integer $l$ and real $x\ge1$ put
97	\[
98	Q(x;q,l)=\#\{n\le x:\ n\equiv l\ (\mathrm{mod}\ q),\ n\text{ squarefree}\}.
99	\]
100	The limit $g(q,l)=\lim_{x\to\infty}Q(x;q,l)/x$ exists; its closed form is recalled in \cref{prop:density}. Unlike the primes, the squarefree numbers populate residue classes that are \emph{not} coprime to the modulus, and their density $g(q,l)$ depends on $l$ through the common divisors of $l$ and $q$. For instance, $g(q,l)=0$ whenever $p^2$ divides both $q$ and $l$ for some prime $p$. The error term
101	\[
102	E(x;q,l)=Q(x;q,l)-g(q,l)\,x
103	\]
104	measures the irregularity of the distribution, and its mean square over all residue classes and all moduli up to $Y$,
105	\[
106	V(x,Y)=\sum_{q\le Y}\sum_{l=1}^{q}E(x;q,l)^2,
107	\]
108	is the squarefree analogue of the Barban--Davenport--Halberstam and Montgomery--Hooley variance for primes \cite{montgomery1970,hooley1975i}.
109	
110	For $Y\le x$ the bound $V(x,Y)\ll_\eps x^{1+\eps}Y$ is Lemma~2.2 of Brüdern, Granville, Perelli, Vaughan and Wooley \cite{bgpvw1998} (with their parameter $k=2$); it is quoted precisely in \cref{quoted:bgpvw} below. Asymptotic formulae for $V(x,Y)$ go back to work of Orr, Warlimont and Croft, surveyed in the introduction of Vaughan's paper \cite{vaughan2005}; according to that survey, Warlimont \cite{warlimont1980} proved $V(x,Y)=x^2\mathcal F(x/Y)+O(x^{3/2}(\log x)^{7/2})$ for $1\le Y\le x$, with $\mathcal F(u)\sim c_2\,u^{-3/2}$ as $u\to\infty$, where $c_2$ is the constant in \eqref{eq:c2} below; and the argument of Croft \cite{croft1975} contains an error affecting the constant. Vaughan \cite[Theorem]{vaughan2005} broke the barrier $x^{3/2}$ inherent in the earlier methods. For squarefree numbers (his $k=2$) his theorem states that, for $Y\le x$,
111	\begin{multline}\label{eq:vaughan}
112	V(x,Y)=c_2x^{1/2}Y^{3/2}+O\Bigl(x^{1/4}Y^{7/4}\exp\Bigl(-c^*\frac{(\log 2x/Y)^{3/5}}{(\log\log 3x/Y)^{1/5}}\Bigr)\Bigr)\\
113	+O\Bigl(x^{3/2}\exp\Bigl(-\tilde c\frac{(\log x)^{3/5}}{(\log\log x)^{1/5}}\Bigr)\Bigr),
114	\end{multline}
115	for certain positive constants $c^*,\tilde c$, where
116	\begin{equation}\label{eq:c2}
117	c_2=\frac{8C_1\,(-\zeta(-\frac12))}{3\,\zeta(2)^2},\qquad
118	C_1=\prod_p\Bigl(1+\frac{(p-1)^2p^{3/2}-2p^4+3p^3-p}{p^2(p^2-1)^2}\Bigr)
119	\end{equation}
120	\cite[(1.13)--(1.15)]{vaughan2005}; in the numerator of the local factor of $C_1$, the term $3p^3$ is the sum $p^{2k-1}+2p^{k+1}$ of Vaughan's general formula at $k=2$. The main term is thus of order $x^{1/2}Y^{3/2}$, much smaller than the ``diagonal'' size $xY$ one might naively expect; this reflects strong cancellation, which will also be the central feature of the present work.
121	
122	\section{Sparse moduli}
123	
124	Brüdern and Wooley \cite{bruedernwooley2011} asked the analogous question for primes when the moduli are restricted to the values $f(k)$ of a polynomial, weighting the modulus $f(k)$ by $f'(k)$. The weight makes the sparse sum behave like the full sum over moduli $q\le f(y)$, since $f'(k)\,\dd k=\dd f(k)$. They established an asymptotic formula of Montgomery--Hooley type for this sparse variance, improving the upper bound of Mikawa and Peneva \cite{mikawapeneva2005}. Their method follows the approach of Goldston and Vaughan \cite{goldstonvaughan1997} and Vaughan \cite{vaughan1998a}: the variance is linked to the number of solutions of $p_1-p_2=hf(k)$, which is then counted by the circle method.
125	
126	This document treats the analogous problem for squarefree numbers. Throughout, $f\in\Z[t]$ is a polynomial of degree $d\ge1$ such that
127	\begin{equation}\label{eq:f-hyp}
128	f(t)\ge2\quad\text{and}\quad f'(t)\ge1\qquad\text{for all real }t\ge1,
129	\end{equation}
130	and
131	\begin{equation}\label{eq:Vf}
132	V_f(x,y)=\sum_{k\le y}f'(k)\sum_{l=1}^{f(k)}E\bigl(x;f(k),l\bigr)^2\qquad(f(y)\le x).
133	\end{equation}
134	Here $k$ runs over positive integers, $y\ge1$ is real, and all residue classes modulo $f(k)$ are included. We write
135	\[
136	\rho(m)=\#\{a\bmod m:\ f(a)\equiv0\ (\mathrm{mod}\ m)\},\qquad \rho(1)=1,
137	\]
138	and $Y=f(y)$. No irreducibility, squarefreeness or discriminant condition is imposed on $f$, and $f$ may have fixed prime divisors.
139	
140	\section{The main result}
141	
142	To state the result we need an arithmetic weight. For a positive integer $h$ and a prime $p$ let $v_p(h)$ be the exponent of $p$ in $h$, and define
143	\begin{equation}\label{eq:W-intro}
144	W_f(h)=\prod_p w_p(h),\qquad
145	w_p(h)=\begin{cases}
146	1-\dfrac2{p^2}+\dfrac{\rho(p^2)}{p^4},& p\nmid h,\\[2mm]
147	1-\dfrac2{p^2}+\dfrac{\rho(p)}{p^3},& p\parallel h,\\[2mm]
148	1-\dfrac1{p^2},& p^2\mid h.
149	\end{cases}
150	\end{equation}
151	Equivalently, $w_p(h)=(1-2p^{-2})\bigl(1+\rho(p^{j})/(p^{j}(p^2-2))\bigr)$ with $j=\max\{2-v_p(h),0\}$. In \cref{ch:averaging} we shall see that $W_f(h)$ is the average over $k$ of the singular series $\Sing(hf(k))$ that governs the number of pairs of squarefree integers with difference $hf(k)$. The product converges absolutely and $0<W_f(h)\le1$ (\cref{lem:W-basic}). Let
152	\[
153	D_f(s)=\sum_{h\ge1}W_f(h)h^{-s}\qquad(\re s>1).
154	\]
155	By \cref{prop:Df}, $D_f$ continues meromorphically to $\re s>-\frac34$, where its only poles are simple poles at $s=1$ and $s=-\frac12$. Define
156	\begin{equation}\label{eq:RBK}
157	R_f=\Res_{s=1}D_f(s),\qquad
158	B_f=\lim_{s\to1}\Bigl(D_f(s)-\frac{R_f}{s-1}\Bigr)-\frac32R_f,\qquad
159	K_f=-\frac{16}{3}\Res_{s=-1/2}D_f(s),
160	\end{equation}
161	and, for real $H\ge1$,
162	\begin{equation}\label{eq:ThetaF}
163	\Theta_f(H)=\sum_{1\le h\le H}W_f(h)\frac{(H-h)^2}{h},\qquad
164	F_f(H)=R_f\log H+B_f+\frac{1}{\zeta(2)H}-\frac{\Theta_f(H)}{H^2}.
165	\end{equation}
166	
167	\begin{theorem}[Main theorem]\label{thm:main}
168	Let $f$ satisfy \eqref{eq:f-hyp}, let $d=\deg f$, and put
169	\[
170	\eta_d=\min\Bigl\{\frac15,\frac1{4d-1}\Bigr\}.
171	\]
172	For every $\eps$ with $0<\eps<\eta_d/2$ there are constants $C(f,\eps)>0$ and $x_0(f,\eps)$ such that, uniformly for real $x\ge x_0(f,\eps)$ and real $y\ge1$ with $Y=f(y)\le x$,
173	\begin{align}
174	\bigl|V_f(x,y)-x^2F_f(x/Y)\bigr|&\le C(f,\eps)\,x^{2-\eta_d+\eps},\label{eq:main1}\\
175	\bigl|V_f(x,y)-K_fx^{1/2}Y^{3/2}\bigr|&\le C(f,\eps)\bigl(x^{3/8}Y^{13/8}+x^{2-\eta_d+\eps}\bigr).\label{eq:main2}
176	\end{align}
177	The constant $K_f$ is positive and is given by the absolutely convergent Euler product
178	\begin{equation}\label{eq:K-intro}
179	K_f=-\frac83\,\zeta(-\tfrac12)\prod_p\Bigl(1-\frac1p\Bigr)\Bigl(1+\frac1p-\frac{2+\rho(p)}{p^2}+\frac{\rho(p)}{p^{5/2}}-\frac{\rho(p^2)}{p^{7/2}}+\frac{\rho(p^2)}{p^4}\Bigr).
180	\end{equation}
181	Moreover
182	\begin{equation}\label{eq:R-intro}
183	R_f=\frac1{\zeta(2)^2}\prod_p\Bigl(1+\frac{(1-1/p)(\rho(p)+\rho(p^2))}{(p^2-1)^2}\Bigr).
184	\end{equation}
185	\end{theorem}
186	
187	The function $F_f$ is explicit, and \cref{prop:Theta} shows that $|F_f(H)-K_fH^{-3/2}|\le C(f)H^{-13/8}$ for all $H\ge1$; \eqref{eq:main2} is \eqref{eq:main1} combined with this expansion at $H=x/Y$. Dividing \eqref{eq:main2} by its main term gives the following.
188	
189	\begin{corollary}\label{cor:range}
190	Let $0<\delta<\eta_d/3$. Uniformly for $x\ge x_0(f,\delta)$ and $x^{1-2\eta_d/3+\delta}\le f(y)\le x^{1-\delta}$,
191	\[
192	V_f(x,y)=K_f\,x^{1/2}f(y)^{3/2}\bigl(1+O_{f,\delta}(x^{-\delta/8})\bigr).
193	\]
194	\end{corollary}
195	
196	The proof of \cref{cor:range} is given in \cref{sec:corollary}. The exponents for small degrees are as follows.
197	
198	\begin{center}
199	\begin{tabular}{@{}cccc@{}}
200	\toprule
201	$d$ & $\eta_d$ & error in \eqref{eq:main1} & range of \cref{cor:range}\\
202	\midrule
203	$1$ & $1/5$ & $x^{9/5+\eps}$ & $x^{13/15+\delta}\le f(y)\le x^{1-\delta}$\\
204	$2$ & $1/7$ & $x^{13/7+\eps}$ & $x^{19/21+\delta}\le f(y)\le x^{1-\delta}$\\
205	$3$ & $1/11$ & $x^{21/11+\eps}$ & $x^{31/33+\delta}\le f(y)\le x^{1-\delta}$\\
206	$d\ge2$ & $1/(4d-1)$ & $x^{2-1/(4d-1)+\eps}$ & $x^{1-2/(3(4d-1))+\delta}\le f(y)\le x^{1-\delta}$\\
207	\bottomrule
208	\end{tabular}
209	\end{center}
210	
211	\begin{remark}[Two regimes]\label{rem:regimes}
212	\Cref{thm:main} distinguishes two descriptions of the variance. Suppose that $Y/x$ tends to zero and that, in addition, the additive error $x^{2-\eta_d+\eps}$ in \eqref{eq:main2} is $o(x^{1/2}Y^{3/2})$; this holds, for instance, throughout the range of \cref{cor:range}. Then \eqref{eq:main2} shows that the variance is asymptotic to the power law $K_fx^{1/2}Y^{3/2}$, as in Vaughan's theorem \eqref{eq:vaughan}. For smaller $Y$ the theorem gives only an upper bound for the difference, and no asymptotic formula. When the ratio $r=Y/x$ is fixed, \eqref{eq:main1} gives $V_f(x,y)=x^2F_f(1/r)+O(x^{2-\eta_d+\eps})$. Here $x^2F_f(1/r)=K_fx^{1/2}Y^{3/2}\cdot F_f(1/r)r^{-3/2}/K_f$, and by \eqref{eq:F-asym} the factor $F_f(1/r)r^{-3/2}/K_f=1+O(r^{1/8})$ is independent of $x$. The theorem does not say that this factor equals one, and the numerical values in \cref{ch:numerics} show that it does not. The normalised quantity $V_f(x,y)/(x^{1/2}Y^{3/2})$ therefore approaches the ratio-dependent profile $F_f(1/r)r^{-3/2}$ rather than the constant $K_f$. This distinction is essential for interpreting the numerical data.
213	\end{remark}
214	
215	\begin{remark}[Consistency with Vaughan's constant]\label{rem:vaughan}
216	For $f(t)=t+1$ one has $\rho(m)=1$ for all $m$, and $V_f(x,y)=V(x,Y)-E(x;1,1)^2$ with $Y=f(y)=y+1$, because the moduli $f(k)=k+1$, $k\le y$, are exactly the integers $2\le q\le Y$; by \cref{prop:density} the subtracted term is $O(x)$. A direct computation shows that for $\rho(p)=\rho(p^2)=1$ each local factor in \eqref{eq:K-intro} equals $(1-p^{-2})^2$ times the local factor of $C_1$ in \eqref{eq:c2}. Since $\prod_p(1-p^{-2})^2=\zeta(2)^{-2}$, it follows that $K_{t+1}=c_2$. Thus the constant of \cref{thm:main} agrees with Vaughan's constant in the one case where both results apply; numerically $K_{t+1}=\KVau$ (see \cref{tab:constants}). For $f(t)=t+1$, \cref{thm:main} is of course much weaker than \eqref{eq:vaughan} as far as the range and the error term are concerned. This comparison was made while preparing this document and is not part of the archived proof (see \cref{app:provenance}).
217	\end{remark}
218	
219	\begin{remark}[Limitations]
220	The asymptotic formula is established only for $f(y)\ge x^{1-2\eta_d/3+\delta}$, not throughout $f(y)\le x$. Two features of the argument fix the exponent $\eta_d$ (see \cref{sec:budget}). The cap $1/5$ comes from summing the error $O(x^{4/5})$ of the correlation estimate (\cref{prop:corr}) over about $x\log x$ pairs $(h,k)$. The exponent $1/(4d-1)$ comes from balancing the bound for small moduli, which is obtained by inserting the full variance bound of \cite{bgpvw1998}, against the error of the averaging over polynomial values in \cref{prop:averaging}.
221	\end{remark}
